def solve(inputs: dict) -> float:
    # Find remainders and moduli lists in inputs
    rem = None
    mod = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            lk = k.lower()
            if 'mod' in lk:
                mod = list(v)
            else:
                rem = list(v)
    # fallback: assign by order
    if rem is None or mod is None:
        lists = [v for v in inputs.values() if isinstance(v, (list, tuple))]
        if len(lists) >= 2:
            rem, mod = list(lists[0]), list(lists[1])
    # CRT
    M = 1
    for m in mod:
        M *= m
    x = 0
    for r, m in zip(rem, mod):
        Mi = M // m
        inv = pow(Mi, -1, m)
        x += r * Mi * inv
    return float(x % M)

