def solve(inputs: dict) -> float:
    mat = None
    power = None
    mod = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            mat = [list(row) for row in v]
        else:
            lk = k.lower()
            if 'mod' in lk:
                mod = int(v)
            elif 'pow' in lk or 'exp' in lk or 'power' in lk:
                power = int(v)
    # fallback for scalars
    if power is None or mod is None:
        scalars = [int(v) for v in inputs.values() if not isinstance(v, (list, tuple))]
        # power likely smaller, mod likely larger; but use key detection primarily
        if power is None:
            power = min(scalars)
        if mod is None:
            mod = max(scalars)

    def matmul(A, B, m):
        n = len(A)
        C = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                s = 0
                for k in range(n):
                    s += A[i][k]*B[k][j]
                C[i][j] = s % m
        return C

    n = len(mat)
    # identity
    result = [[1 if i==j else 0 for j in range(n)] for i in range(n)]
    base = [[mat[i][j] % mod for j in range(n)] for i in range(n)]
    p = power
    while p > 0:
        if p & 1:
            result = matmul(result, base, mod)
        base = matmul(base, base, mod)
        p >>= 1
    total = sum(result[i][j] for i in range(n) for j in range(n))
    return float(total)

